TYPE Event = Frozen<{
    causal_id    : CausalID,
    commit_index : CommitIndex,
    payload      : EventPayload
  }>

TYPE DelegationGraph = {
    allows : CanonicalAuthority -> ExecutionAuthority -> Prop
  }

TYPE ExecutionAuthorityGrant(graph : DelegationGraph) = {
    source    : CanonicalAuthority,
    execution : ExecutionAuthority,
    proof     : graph.allows(source, execution)
  }

TYPE CheckEvidence = {
    proposal_id : String,
    check_name  : String,
    result      : ValidationJudgement,
    evidence    : String
  }

TYPE ProposedProposal = {
    proposal_id : String,
    payload     : String
  }

TYPE ValidatedProposal = {
    base   : ProposedProposal,
    checks : List<CheckEvidence>,
    proof  : Forall(e ∈ checks, (e.result == CheckSucceeded) ∧ (e.proposal_id == base.proposal_id))
  }

TYPE CommittedProposal(graph : DelegationGraph) = {
    validated  : ValidatedProposal,
    capability : CommitCapability(graph)
  }

TYPE CanonicalAuthority = {
    causal         : CausalAuthority,
    interpretation : InterpretationAuthority
  }

TYPE KernelAction(ctx : KernelContext) = {
    name   : String,
    intent : Intent
  }

TYPE EventFact(ctx : KernelContext, p1 : Projection, p2 : Projection, act : KernelAction(ctx)) = {
    action_name      : String,
    obs              : Observation(p1, p2),
    transition_proof : p2 == apply_intent(act.intent, p1),
    authority_proof  : Executable(ctx, act)
  }

TYPE InternalCapability(ctx : KernelContext) = {
    grant          : CanonicalAuthority,
    scope_boundary : String,
    allowed_action : KernelAction(ctx) -> Prop,
    executable     : Forall(a : KernelAction(ctx), allowed_action(a) -> Executable(ctx, a))
  }

TYPE DerivedData = Frozen<{
    representation : String,
    origin         : ProjectionOrigin
  }>

TYPE PipelineState = Frozen<{
    projection_model : ProjectionState,
    semantic_model   : SemanticState,
    graph            : GraphState
  }>

TYPE ReplayContext = Frozen<{
    history              : History,
    abi_snapshot         : ABIRegistrySnapshot,
    constitution_version : Version
  }>

DEF execute_pipeline(
    ctx : ReplayContext
  ) -> Result<PipelineState, PipelineExecutionError>

