} : immutable

TYPE PrefillState = {
  context: [ContextNode],
  target_id: NodeID,
  hash: String                // SHA256 of materialized canonical prompt
} : immutable

lift(k) -> Graph:
  g = {nodes: {}, edges: [], par: {}}
  ht = {}
  last = null
  for e in k.wal.store:
    n = {id: e.idx, ev: e, cls: classify(e.kind), clk: e.clk, wld: e.wld}
    g.nodes[n.id] = n
    if last != null:
      g.edges.append({src: last.id, dst: n.id, typ: Temporal})
      g.par[n.id] = last.id
    if n.cls != Fault:
      if ht[e.wld] != null:
        g.edges.append({src: ht[e.wld], dst: n.id, typ: Causal})
      ht[e.wld] = n.id
    last = n
  return g

